import React from 'react';

export default function EquipmentDetailModal({ equipment, onClose, onBorrowClick }) {
  if (!equipment) return null;

  return (
    <div style={{
      position: 'fixed',
      top: 0,
      left: 0,
      width: '100%',
      height: '100%',
      background: 'rgba(0, 0, 0, 0.5)',
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      zIndex: 1000,
      padding: '20px'
    }}>
      <div style={{
        background: '#FFFFFF',
        borderRadius: '16px',
        maxWidth: '550px',
        width: '100%',
        overflow: 'hidden',
        boxShadow: '0 10px 25px rgba(0,0,0,0.15)',
        animation: 'fadeIn 0.2s ease-in-out'
      }}>
        {/* รูปภาพอุปกรณ์ */}
        <div style={{ width: '100%', height: '260px', background: '#F1F5F9', position: 'relative' }}>
          <img 
            src={equipment.image} 
            alt={equipment.name} 
            style={{ width: '100%', height: '100%', objectFit: 'cover' }}
          />
          <span style={{
            position: 'absolute',
            top: '16px',
            left: '16px',
            background: 'rgba(30, 58, 138, 0.85)',
            color: '#FFFFFF',
            padding: '6px 14px',
            borderRadius: '20px',
            fontSize: '13px',
            fontWeight: '600',
            backdropFilter: 'blur(4px)'
          }}>
            {equipment.category}
          </span>
        </div>

        {/* รายละเอียด */}
        <div style={{ padding: '24px' }}>
          <h3 style={{ margin: '0 0 10px 0', color: '#1E293B', fontSize: '20px' }}>
            {equipment.name}
          </h3>

          <div style={{ display: 'flex', gap: '15px', marginBottom: '16px', fontSize: '14px', color: '#64748B' }}>
            <span>📦 สต็อกทั้งหมด: <strong>{equipment.totalStock} ชิ้น</strong></span>
            <span>✨ คงเหลือให้ยืม: <strong style={{ color: equipment.availableStock > 0 ? '#16A34A' : '#DC2626' }}>{equipment.availableStock} ชิ้น</strong></span>
          </div>

          <div style={{ background: '#F8FAFC', padding: '14px', borderRadius: '10px', marginBottom: '24px', border: '1px solid #E2E8F0' }}>
            <h4 style={{ margin: '0 0 6px 0', fontSize: '14px', color: '#334155' }}>รายละเอียด / คำอธิบาย:</h4>
            <p style={{ margin: 0, fontSize: '14px', color: '#475569', lineHeight: '1.5' }}>
              {equipment.description || 'ไม่มีคำอธิบายเพิ่มเติมสำหรับอุปกรณ์ชิ้นนี้'}
            </p>
          </div>

          {/* ปุ่มควบคุมด้านล่าง */}
          <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px' }}>
            <button 
              onClick={onClose}
              style={{
                padding: '10px 20px',
                background: '#F1F5F9',
                color: '#475569',
                border: 'none',
                borderRadius: '8px',
                fontWeight: '600',
                cursor: 'pointer',
                fontSize: '14px'
              }}
            >
              ปิด
            </button>

            {equipment.availableStock > 0 && (
              <button 
                onClick={() => {
                  onClose();
                  onBorrowClick(equipment); // เปิด Modal ขอยืมต่อได้เลย
                }}
                style={{
                  padding: '10px 20px',
                  background: '#2563EB',
                  color: '#FFFFFF',
                  border: 'none',
                  borderRadius: '8px',
                  fontWeight: '600',
                  cursor: 'pointer',
                  fontSize: '14px'
                }}
              >
                ยืมอุปกรณ์นี้
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
